using System;using System.Collections.Generic;using Ashfall.Core;using Ashfall.Modules.Pickups;using Ashfall.Modules.HealthStates;using Ashfall.Integration.Playable.Consumables;
namespace Ashfall.Integration.Playable.Networking {
 // Host-loaded source asset geometry; callers never supply a gesture-ready bit.
 public interface IR24LanFoodGeometry {bool TryFrame(string kind,int hand,R24LanRawTracking raw,out ActorFrame frame);}
 public sealed partial class R24LanLobby {
  IR24LanFoodGeometry foodGeometry;readonly Dictionary<string,FoodPreparation> foodPreparations=new Dictionary<string,FoodPreparation>(StringComparer.Ordinal);
  sealed class FoodPreparation {internal string Id;internal int Hand;internal long Life;internal double At;internal bool PreviousGrip;internal R23ConsumableState State;internal ActorFrame Frame;}
  sealed class PreparationPorts:IR23ConsumableEffects,IInteractionQuery {readonly R24LanLobby owner;readonly string actor;internal PreparationPorts(R24LanLobby owner,string actor){this.owner=owner;this.actor=actor;}public R23ConsumableVitals ReadVitals(){var m=owner.sessions.Get(actor);var h=m==null?null:owner.hostHealth.Read(m.CanonicalActorId);return new R23ConsumableVitals{Health=h==null?0:h.Health,Shield=h==null?0:h.Shield,Alive=h!=null&&h.Connected&&h.Life==LifeState.Alive};}public bool TryApplyGain(float hp,float shield,bool stamina){return false;}public bool HasLineOfSight(string actor,string target,Float3 from,Float3 to,float range){return owner.rawWorldClear!=null&&owner.rawWorldClear(from,to);}}
  public void BindFoodGeometry(IR24LanFoodGeometry geometry){Check();if(State!=R24LanLobbyState.Hosting||geometry==null||foodGeometry!=null)throw new InvalidOperationException("One host source food geometry required");foodGeometry=geometry;}
  bool EquipFood(string actor,R24LanFoodState food,int hand,R24LanRawTracking raw){if(foodGeometry==null||ControlsBlocked(actor)||raw.Paddles||HandOccupied(actor,hand)||GrenadeHandOccupied(actor,hand))return false;var m=sessions.Get(actor);var h=m==null?null:hostHealth.Read(m.CanonicalActorId);if(h==null||h.Life!=LifeState.Alive)return false;FoodPreparation old;if(foodPreparations.TryGetValue(actor,out old)&&old.Id==food.Id&&old.Hand==hand&&old.Life==h.LifeGeneration&&old.State.HeldId==food.Id)return true;
   ActorFrame frame;if(!foodGeometry.TryFrame(food.Kind,hand,raw,out frame)||!FoodFrameValid(frame)||!rawWorldClear(frame.Head,frame.Hand))return false;frame.OtherHandEligible&=!HandOccupied(actor,1-hand)&&!GrenadeHandOccupied(actor,1-hand);var ports=new PreparationPorts(this,actor);var state=new R23ConsumableState(ports,ports);state.Register(food.Id,food.Kind,frame.Hand,false);state.SetFrame(frame);state.Advance(0);
   if(!state.Execute(PickupAction.Reserve,food.Id).Accepted||!state.Execute(PickupAction.Collect,food.Id).Accepted||!state.Execute(PickupAction.Equip,food.Id).Accepted)return false;
   foodPreparations[actor]=new FoodPreparation{Id=food.Id,Hand=hand,Life=h.LifeGeneration,At=clock.Now,PreviousGrip=frame.OtherGrip,State=state,Frame=frame};return true;
  }
  static bool FoodFrameValid(ActorFrame f){return f!=null&&f.Allowed&&f.HandEligible&&f.Head.IsFinite&&f.Hand.IsFinite&&f.Forward.IsFinite&&f.LocalHand.IsFinite&&f.OtherLocal.IsFinite&&f.Anchor.IsFinite&&f.HeadLocalAnchor.IsFinite&&!Single.IsNaN(f.ItemUpDot)&&!Single.IsInfinity(f.ItemUpDot);}
  void SampleFoodPose(string actor,R24LanRawTrackingSample sample){FoodPreparation prep;R24LanFoodState food;if(!InventoryLive||foodGeometry==null||!foodPreparations.TryGetValue(actor,out prep)||!foods.TryGetValue(prep.Id,out food)||food.Owner!=actor||food.Consumed)return;var member=sessions.Get(actor);var h=member==null?null:hostHealth.Read(member.CanonicalActorId);ActorFrame frame;double dt=clock.Now-prep.At;
   if(h==null||h.Life!=LifeState.Alive||h.LifeGeneration!=prep.Life||ControlsBlocked(actor)||sample.Pose.Paddles||dt>.1+.000001||dt<0||!foodGeometry.TryFrame(food.Kind,prep.Hand,sample.Pose,out frame)||!FoodFrameValid(frame)){ResetFoodPreparation(actor);return;}if(dt<=0)return;frame.OtherHandEligible&=!HandOccupied(actor,1-prep.Hand)&&!GrenadeHandOccupied(actor,1-prep.Hand);prep.At=clock.Now;prep.Frame=frame;prep.State.SetFrame(frame);prep.State.Advance((float)Math.Min(.1,dt));bool edge=frame.OtherGrip&&!prep.PreviousGrip;prep.PreviousGrip=frame.OtherGrip;
   if(edge&&frame.OtherHandEligible&&prep.State.Phase==Preparation.Open)prep.State.Execute(food.Kind=="banana"?PickupAction.BeginPeel:PickupAction.Open,food.Id);
   if(food.Kind=="banana"&&prep.State.Phase==Preparation.Open)prep.State.Execute(PickupAction.SamplePeel,food.Id);if(prep.State.Phase==Preparation.Shake)prep.State.Execute(PickupAction.SampleShake,food.Id);
  }
  bool FoodReady(string actor,string id,int hand){FoodPreparation prep;if(!foodPreparations.TryGetValue(actor,out prep)||prep.Id!=id||prep.Hand!=hand||clock.Now-prep.At>.1+.000001||prep.State.Phase!=Preparation.Consume||!FoodFrameValid(prep.Frame))return false;var f=prep.Frame;var food=foods[id];bool mouth=Distance2(f.Anchor,f.Head)<=.450001f*.450001f||Math.Abs(f.HeadLocalAnchor.X)<=.25f&&f.HeadLocalAnchor.Y>=-.35f&&f.HeadLocalAnchor.Y<=.12f&&f.HeadLocalAnchor.Z>=-.05f&&f.HeadLocalAnchor.Z<=.50f;
   return mouth&&(food.Kind=="banana"||f.ItemUpDot<.75f)&&rawWorldClear!=null&&rawWorldClear(f.Anchor,f.Head);
  }
 }
}
